/* BlueprintReq: page-based product workspace based on the supplied screen reference. */
let sectionIndex=0,sectionDrafts={},aiProposals={},requestMode='text',requirementsQuery='',moduleFilter='All modules',storyQuery='',appSearch='',meetingLanguage='en-ja';
const sectionTitles=['Introduction','Overall description','Functional requirements','Non-functional requirements','Business rules','Assumptions & constraints','Glossary'];
const pageNames={dashboard:'Dashboard',request:'New requirement request',meetings:'Live meeting',srs:'Software requirements specification',baseline:'Review & approve SRS',requirements:'Requirements management',stories:'User stories & acceptance criteria',timeline:'Project timeline & estimation',architecture:'System architecture',tests:'Test cases',quality:'Quality assurance',traceability:'Requirements traceability',projects:'Projects',workspaces:'Workspaces',teams:'Teams',users:'User management',roles:'Roles',permissions:'Permissions',usage:'Usage',profile:'My profile',create:'Create'};
const workflowNav=[['request','New request','plus'],['meetings','Live meeting','teams'],['srs','SRS document','requirements'],['baseline','Baseline approval','roles'],['requirements','Requirements','requirements'],['stories','User stories','projects'],['timeline','Timeline','dashboard'],['architecture','Architecture','workspaces'],['tests','Test cases','check'],['quality','Quality assurance','roles'],['traceability','Traceability','workspaces']];
function bpLogo(){return '<span class="bp-logo-mark">B<span>r</span></span><span class="bp-logo-name">Blueprint<span>Req</span></span>'}
function appProject(){projectReady();return projects.find(p=>p.id===selected)}
function docs(){if(!selected)return [];if(!sectionDrafts[selected]){const p=appProject();sectionDrafts[selected]=['This document defines the requirements for '+p.name+'.\n\nObjective\n'+p.desc+'.\n\nThe proposed application brings project information, deliverable reviews, and stakeholder communication into one secure workspace.','Users include project owners, team members, reviewers, and clients. Each user works within an assigned workspace and project.','FR-001 · Access control\nUsers can access only projects assigned to their organization.\n\nFR-002 · Deliverable review\nAssigned reviewers can leave feedback and record an approval decision.\n\nFR-003 · Notifications\nStakeholders are informed when deliverables are ready for review.','Security\nEnforce project permissions on every request.\n\nReliability\nRecord failed notification delivery attempts.\n\nPerformance\nResponse-time targets require stakeholder confirmation.','Only authorized reviewers can approve a baseline. An approved baseline is locked. Changes require a new draft and renewed approval.','Assumptions\nA project owner will identify the final approver.\n\nOpen decisions\nConfirm notification timing, expected user volume, retention period, and supported integrations.','SRS — Software Requirements Specification\nBaseline — An approved version used as the basis for planning.\nAcceptance criteria — Observable conditions that determine whether a requirement is satisfied.']};return sectionDrafts[selected]}
function sectionSave(){const el=$('#sectionEditor');if(el&&selected&&!current().approved){const text=el.value;if(docs()[sectionIndex]!==text){docs()[sectionIndex]=text;current().reviewed=false}}}
const captureBeforeBlueprint=captureReq;
captureReq=function(){sectionSave();captureBeforeBlueprint()};
function chooseSection(i){sectionSave();sectionIndex=i;render()}
function jumpPage(route){captureReq();screen=route;filter='';history.replaceState(null,'','#'+route);document.body.classList.remove('bp-nav-open');render();window.scrollTo?.(0,0)}
navigate=jumpPage;
openProject=function(id){captureReq();selected=id;screen='srs';sectionIndex=0;history.replaceState(null,'','#srs');render()};
function selectProject(id){captureReq();selected=Number(id);sectionIndex=0;render()}
function bpHeading(title,sub,action=''){return '<div class="page-head"><div><h1>'+title+'</h1><p class="sub">'+sub+'</p></div><div class="actions">'+action+'</div></div>'}
function bpProjectPicker(){return '<select class="project-select" aria-label="Choose project" onchange="selectProject(this.value)">'+projects.filter(p=>p.space===workspace).map(p=>'<option value="'+p.id+'" '+(p.id===selected?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select>'}
function pageLink(route,label,glyph){return '<a href="#'+route+'" class="bp-nav-link '+(screen===route?'active':'')+'">'+icon(glyph||route)+'<span>'+label+'</span></a>'}
function projectSteps(p){const r=reqs[p.id]??(reqs[p.id]=initial(p)),plan=plans[p.id],arch=architectures[p.id],hasBrief=!!r?.brief?.trim(),hasSrs=!!r?.doc?.trim(),approved=!!r?.approved,hasBacklog=!!plan?.rows?.length,planApproved=!!plan?.approved,hasArch=!!arch?.doc?.trim(),archApproved=!!arch?.approved;return [['srs','SRS document','requirements',hasBrief],['baseline','Baseline approval','roles',hasSrs],['requirements','Requirements','requirements',approved],['stories','User stories','projects',approved&&hasBacklog],['timeline','Timeline','dashboard',approved&&hasBacklog],['architecture','Architecture','workspaces',approved&&planApproved],['tests','Test cases','check',approved&&hasArch],['quality','Quality assurance','roles',approved&&hasArch],['traceability','Traceability','workspaces',approved&&archApproved]]}
let collapsedProjects=new Set();
function projectTreeNav(){const ps=projects.filter(p=>p.space===workspace);return '<div class="bp-nav-label project-nav-label">PROJECTS</div>'+ps.map(p=>{const open=selected===p.id&&!collapsedProjects.has(p.id);return '<div class="sidebar-project"><button class="sidebar-project-name" aria-expanded="'+open+'" onclick="toggleProjectGroup('+p.id+')"><span class="project-chevron">'+(open?'⌄':'›')+'</span>'+icon('projects')+'<span>'+esc(p.name)+'</span></button><div class="sidebar-project-steps '+(open?'':'collapsed')+'">'+(open?projectSteps(p).map(([r,t,i,show])=>show?'<a href="#'+r+'" class="bp-nav-link compact '+(screen===r&&selected===p.id?'active':'')+'" onclick="selected='+p.id+'">'+icon(i)+'<span>'+t+'</span></a>':'').join(''):'')+'</div></div>'}).join('')+(ps.length?'':'<div class="sidebar-empty">Create a project to unlock its workflow.</div>')}
function toggleProjectGroup(id){if(collapsedProjects.has(id))collapsedProjects.delete(id);else collapsedProjects.add(id);render()}
function bpShell(content){return '<aside class="bp-sidebar"><a class="bp-brand" href="#dashboard">'+bpLogo()+'</a><div class="sidebar-workspace"><span>WORKSPACE</span><div><select aria-label="Choose workspace" onchange="switchWorkspace(Number(this.value))">'+spaces.map(w=>'<option value="'+w.id+'" '+(w.id===workspace?'selected':'')+'>'+esc(w.name)+'</option>').join('')+'</select><button class="iconbtn" aria-label="Create workspace" onclick="openCreate(\'workspace\')">+</button></div></div><div class="bp-nav-scroll">'+pageLink('dashboard','Home','dashboard')+('<button class="bp-nav-link" style="width:100%;border:0;background:transparent;text-align:left" onclick="openCreate(\'project\')">'+icon('plus')+'<span>New project</span></button>')+projectTreeNav()+'<div class="bp-nav-label">ORGANIZATION</div>'+[['projects','Projects'],['teams','Team'],['workspaces','Workspaces'],['users','User management'],['roles','Roles'],['permissions','Permissions'],['usage','Usage']].map(([r,t])=>pageLink(r,t,r)).join('')+'</div><a class="sidebar-person" href="#profile">'+avatar(profile.name)+'<span><b>'+esc(profile.name)+'</b><small>Workspace owner</small></span>'+icon('arrow')+'</a></aside><div class="bp-layout"><header class="bp-header"><button class="mobile-toggle iconbtn" aria-label="Open navigation" onclick="document.body.classList.toggle(\'bp-nav-open\')">☰</button><div class="header-workspace-label">'+esc(spaces[workspace].name)+'</div><span class="header-divider"></span><span class="header-page">'+esc(pageNames[screen]||'Workspace')+'</span><div class="header-tools"><a class="iconbtn" href="#usage" aria-label="Usage">'+icon('dashboard')+'</a><a href="#profile" aria-label="Profile">'+avatar(profile.name)+'</a></div></header><main class="bp-main">'+content+'</main><footer>BlueprintReq <span>Sample AI output · Changes last for this session</span></footer></div>'}
function emptyProject(){return bpHeading('Start with a project','Create a project in this workspace to begin.',button('+ Create project',"openCreate('project')",true))}
function appNav(){return '<div class="context-bar"><a href="#projects">Projects</a><span> / </span>'+bpProjectPicker()+'<span class="context-status">'+badge(current().approved?'Approved':'Draft')+'</span></div>'}
function requestPage(){return appNav()+bpHeading('New requirement request','Provide your input in any format. We’ll help you turn it into clear requirements.')+'<section class="panel request-panel"><div class="input-options">'+[['text','requirements','Text input','Describe your idea in your own words.'],['upload','projects','Upload documents','Add a supporting TXT or Markdown file.'],['meeting','teams','Meeting recording','Record meeting audio for transcription and translation.']].map(([mode,i,t,d])=>'<button class="input-option '+(requestMode===mode?'selected':'')+'" onclick="captureReq();requestMode=\''+mode+'\';'+(mode==='meeting'?"navigate('meetings')":"render()")+'"><span class="input-icon">'+icon(i)+'</span><b>'+t+'</b><small>'+d+'</small></button>').join('')+'</div>'+(requestMode==='upload'?'<label class="upload-zone">'+icon('projects')+'<b>Choose a supporting document</b><span>TXT or Markdown · Maximum 1 MB</span><input type="file" accept=".txt,.md" onchange="readFile(this)"></label>':'')+'<label class="field request-label">Describe your product idea, requirements, or business needs<textarea id="brief" '+(current().approved?'disabled':'')+' placeholder="What are you building, who is it for, and what should it do?">'+esc(current().brief)+'</textarea></label><div class="request-bottom"><span class="sub">'+esc(current().source)+'</span>'+button('Continue to SRS →','continueRequest()',true)+'</div></section>'}
function continueRequest(){captureReq();if(current().approved)return navigate('srs');if(!current().brief.trim())return toast('Add a project brief first.');docs();docs()[0]=current().brief;jumpPage('srs')}
function srsPage(){const r=current();return appNav()+bpHeading('Software requirements specification','Review and refine every section, with AI suggestions only when you request them.',button('Export','exportSections()')+button('Review baseline →',"navigate('baseline')",true))+'<div class="srs-workspace"><section class="section-list"><h2>Sections</h2>'+sectionTitles.map((t,i)=>'<button class="'+(i===sectionIndex?'selected':'')+'" onclick="chooseSection('+i+')">'+(i+1)+'. '+t+'</button>').join('')+'<div class="section-progress"><b>'+sectionTitles.length+' sections</b><span>Human review required</span></div></section><section class="srs-editor panel"><div class="editor-title"><h2>'+(sectionIndex+1)+'. '+sectionTitles[sectionIndex]+'</h2>'+badge(r.approved?'Approved':'Draft')+'</div><div class="editor-format"><span>Plain text section</span><span>'+ (r.approved?'Read only':'Editable by you')+'</span></div><textarea id="sectionEditor" aria-label="Edit '+sectionTitles[sectionIndex]+'" '+(r.approved?'disabled':'')+'>'+esc(docs()[sectionIndex])+'</textarea>'+(aiProposals[selected+'-'+sectionIndex]?'<div class="ai-proposal"><div><b>✦ AI suggestion · Example</b><button class="iconbtn" aria-label="Dismiss suggestion" onclick="delete aiProposals[selected+\'-\'+sectionIndex];render()">×</button></div><p>'+esc(aiProposals[selected+'-'+sectionIndex])+'</p>'+button('✓ Accept suggestion','acceptSectionAI()')+'</div>':'')+'<div class="editor-footer"><span>Section '+(sectionIndex+1)+' of '+sectionTitles.length+'</span>'+button('Save section',"sectionSave();toast('Section saved for this session.')")+'</div></section><section class="ai-edit-panel panel"><h2>✦ Edit with AI</h2><p class="sub">Choose how to refine this section.</p>'+['Improve writing','Expand content','Shorten content','Clarify acceptance criteria','Check assumptions'].map((t,i)=>'<button onclick="proposeSectionAI('+i+')">'+icon('requirements')+t+'</button>').join('')+'<div class="ai-limit">Example suggestions only. An AI service is not connected.</div></section></div>'}
function proposeSectionAI(i){sectionSave();if(current().approved)return toast('Create a new draft to change an approved baseline.');aiProposals[selected+'-'+sectionIndex]=['Clarify the intended user, the action they can perform, and the expected outcome for this section.','Add scope boundaries, stakeholder responsibilities, and a measurable success condition.','Keep the main requirement in one sentence, then list exceptions separately.','Define an observable pass/fail condition and include a negative test case.','Confirm approval ownership, notification timing, retention, and expected usage before implementation.'][i];track('Section suggestion previewed','Requirements');render()}
function acceptSectionAI(){const key=selected+'-'+sectionIndex;if(current().approved)return;docs()[sectionIndex]+='\n\nProposed refinement — stakeholder confirmation required\n'+aiProposals[key];delete aiProposals[key];current().reviewed=false;track('Section suggestion accepted','Requirements');render()}
function exportSections(){sectionSave();downloadText('BlueprintReq-SRS.txt',sectionTitles.map((t,i)=>(i+1)+'. '+t+'\n\n'+docs()[i]).join('\n\n--------------------\n\n'))}
let baselineChecks={};
function baselinePage(){const r=current(),checks=baselineChecks[selected]??(baselineChecks[selected]=[false,false,false,false]);return appNav()+bpHeading('Review & approve SRS','Review the complete SRS and approve the baseline to proceed to requirement planning.')+'<div class="baseline-grid"><section class="panel"><div class="panel-title"><h2>SRS summary</h2>'+icon('requirements')+'</div><div class="summary-body"><div class="version-tile"><span class="input-icon">'+icon('requirements')+'</span><div><b>'+esc(appProject().name)+'</b><small>Working version · '+(r.approved?'Approved baseline':'Draft for review')+'</small></div></div><div class="summary-counts"><div><b>7</b><span>Sections</span></div><div><b>'+backlog().rows.length+'</b><span>Requirements</span></div><div><b>'+docs().filter(Boolean).length+'</b><span>Populated sections</span></div></div><p class="sub">Check scope, assumptions, business rules, and acceptance outcomes before approval.</p><a class="text-link" href="#srs">← Return to the document</a></div></section><section class="panel"><div class="panel-title"><h2>Approval checklist</h2></div><div class="summary-body">'+['All sections reviewed','Requirements are clear','No critical gaps remain','Stakeholder feedback incorporated'].map((t,i)=>'<label class="approval-check"><input type="checkbox" '+(checks[i]?'checked':'')+' '+(r.approved?'disabled':'')+' onchange="baselineChecks[selected]['+i+']=this.checked">'+t+'</label>').join('')+'<label class="field">Review comments (optional)<textarea class="short-text" id="reviewComment" placeholder="Add your comments…"></textarea></label></div></section></div>'+(r.approved?'<div class="success-strip">✓ Requirements baseline approved. The SRS is locked.</div>':'')+'<div class="page-actions">'+button(r.approved?'Create new draft':'Request changes',r.approved?'reopenSRS()':"navigate('srs')")+button(r.approved?'Continue to requirements →':'Approve baseline',r.approved?"navigate('requirements')":'approveSRS()',true)+'</div>'}
function approveSRS(){if(!baselineChecks[selected]?.every(Boolean))return toast('Complete every approval checklist item.');const r=current();r.approved=true;r.reviewed=true;projects.find(p=>p.id===selected).status='Approved';track('Requirements baseline approved','Requirements');render();toast('Baseline approved. Planning is ready.')}
function reopenSRS(){current().approved=false;current().reviewed=false;baselineChecks[selected]=[false,false,false,false];delete architectures[selected];if(plans[selected])plans[selected].approved=false;navigate('srs')}
function backlog(){const p=planState();if(!p.rows.length&&selected<=4)p.rows=[{id:'REQ-001',module:'Authentication',story:'User registration',ac:'A valid new account can be created; duplicate emails are rejected.',priority:'High',hours:16,status:'Approved'},{id:'REQ-002',module:'Authentication',story:'User login',ac:'Valid credentials open the workspace; invalid credentials return an error.',priority:'High',hours:16,status:'Approved'},{id:'REQ-003',module:'Authentication',story:'Reset password',ac:'A reset link expires after use and does not expose account information.',priority:'Medium',hours:12,status:'Draft'},{id:'REQ-004',module:'Projects',story:'Project management',ac:'Authorized members can create and update assigned projects.',priority:'High',hours:24,status:'Approved'},{id:'REQ-005',module:'Review',story:'Deliverable review',ac:'Reviewer decisions include author, timestamp, and deliverable version.',priority:'High',hours:24,status:'In review'},{id:'REQ-006',module:'Notifications',story:'Review notifications',ac:'Assigned reviewers receive an alert and failed attempts are recorded.',priority:'Medium',hours:16,status:'Draft'},{"id": "REQ-007", "parentId": "REQ-001", "story": "Email verification", "module": "Authentication", "priorityPoints": 90, "priority": "High", "status": "Approved", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-008", "parentId": "REQ-007", "story": "Send verification email", "module": "Authentication", "priorityPoints": 85, "priority": "High", "status": "Approved", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-009", "parentId": "REQ-007", "story": "Validate verification link", "module": "Authentication", "priorityPoints": 80, "priority": "High", "status": "Approved", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-010", "parentId": "REQ-001", "story": "Account profile setup", "module": "Authentication", "priorityPoints": 70, "priority": "High", "status": "Draft", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-011", "parentId": "REQ-004", "story": "Project member management", "module": "Projects", "priorityPoints": 90, "priority": "High", "status": "Approved", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-012", "parentId": "REQ-011", "story": "Assign workspace members", "module": "Projects", "priorityPoints": 85, "priority": "High", "status": "Approved", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-013", "parentId": "REQ-011", "story": "Remove project members", "module": "Projects", "priorityPoints": 65, "priority": "Medium", "status": "Draft", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-014", "parentId": "REQ-004", "story": "Project settings", "module": "Projects", "priorityPoints": 70, "priority": "High", "status": "Approved", "ac": "", "userStory": "", "hours": 8},{"id": "REQ-015", "parentId": "REQ-014", "story": "Update project details", "module": "Projects", "priorityPoints": 60, "priority": "Medium", "status": "Draft", "ac": "", "userStory": "", "hours": 8}];return p}
function filteredRows(){return backlog().rows.filter(r=>(moduleFilter==='All modules'||r.module===moduleFilter)&&(r.story+' '+r.id).toLowerCase().includes(requirementsQuery.toLowerCase()))}
function moduleSelect(){return '<select aria-label="Filter by module" onchange="moduleFilter=this.value;render()">'+['All modules',...new Set(backlog().rows.map(r=>r.module))].map(m=>'<option '+(m===moduleFilter?'selected':'')+'>'+esc(m)+'</option>').join('')+'</select>'}
function priorityTag(p){return '<span class="priority '+p.toLowerCase()+'">'+esc(p)+'</span>'}
function requirementTable(){return table(['ID','Requirement name','Module','Priority','Status','Actions'],filteredRows().map(r=>['<b>'+r.id+'</b>',esc(r.story),esc(r.module),priorityTag(r.priority),badge(r.status||'Draft'),button('Edit',"editRequirement('"+r.id+"')")]))}
function requirementsPage(){return appNav()+bpHeading('Requirements management','Organize functional requirements, priorities, and review status.',moduleSelect()+button('+ Add requirement','editRequirement()',true))+'<section class="panel"><div class="toolbar"><label class="search-field">'+icon('search')+'<input placeholder="Search requirements…" aria-label="Search requirements" value="'+esc(requirementsQuery)+'" oninput="requirementsQuery=this.value;document.getElementById(\'requirementsTable\').innerHTML=requirementTable()"></label><span class="sub">'+backlog().rows.length+' requirements · Example project data</span></div><div id="requirementsTable">'+requirementTable()+'</div></section><div class="page-actions">'+button('Continue to user stories →',"navigate('stories')",true)+'</div>'}
function editRequirement(id){const r=backlog().rows.find(r=>r.id===id)||{story:'',module:'General',priority:'Medium',status:'Draft',ac:'',hours:8};creationPage={title:id?'Edit requirement':'Add requirement',back:'requirements',body:field('Requirement name','story',r.story)+field('Module','module',r.module)+'<div class="form-grid"><label class="field">Priority<select name="priority">'+['High','Medium','Low'].map(p=>'<option '+(p===r.priority?'selected':'')+'>'+p+'</option>').join('')+'</select></label><label class="field">Status<select name="status">'+['Draft','In review','Approved'].map(p=>'<option '+(p===r.status?'selected':'')+'>'+p+'</option>').join('')+'</select></label></div>',submit:"saveRequirement(event,'"+(id||'')+"')"};navigate('create')}
function saveRequirement(e,id){e.preventDefault();const f=Object.fromEntries(new FormData(e.target));if(!f.story.trim()||Number(f.hours)<1)return toast('Enter a name and positive effort estimate.');let p=backlog(),r=p.rows.find(r=>r.id===id);if(r)Object.assign(r,f,{hours:Number(f.hours)});else p.rows.push({...f,id:'REQ-'+String(p.rows.length+1).padStart(3,'0'),hours:Number(f.hours)});p.approved=false;p.reviewed=false;delete architectures[selected];track('Requirement updated','Planning');navigate('requirements')}
function storiesPage(){return appNav()+bpHeading('User stories & acceptance criteria','Turn each requirement into a clear user outcome.',button('+ Add story','editRequirement()',true))+'<div class="story-list">'+backlog().rows.map((r,i)=>'<section class="panel story-card"><div class="story-head"><b>US-'+String(i+1).padStart(3,'0')+'</b>'+badge(r.status||'Draft')+'</div><h2>As a team member, I want '+esc(r.story.toLowerCase())+' so I can complete my project work.</h2><div class="story-meta"><span class="badge blue">'+esc(r.module)+'</span>'+priorityTag(r.priority)+'<span>'+r.id+'</span></div><div class="acceptance"><b>Acceptance criteria</b><p>✓ '+esc(r.ac)+'</p></div><button class="text-link" onclick="editRequirement(\''+r.id+'\')">Edit story details</button></section>').join('')+'</div><div class="page-actions">'+button('Generate timeline →',"navigate('timeline')",true)+'</div>'}
let timelineSettings={};
function timelineState(){return timelineSettings[selected]??(timelineSettings[selected]={frontend:2,backend:2,qa:1,hours:8,days:5,buffer:20,start:'2026-09-21'})}
function timelineCalc(){const t=timelineState(),effort=backlog().rows.reduce((s,r)=>s+(Number(r.hours)||0),0),capacity=(t.frontend+t.backend+t.qa)*t.hours*t.days,total=Math.ceil(effort*(1+t.buffer/100)),weeks=capacity?Math.max(1,Math.ceil(total/capacity)):0;return{effort,total,capacity,weeks}}
function timelinePage(){const t=timelineState(),calc=timelineCalc();return appNav()+bpHeading('Project timeline & estimation','Configure your team and estimate a delivery window.')+'<section class="panel"><div class="panel-title"><h2>Team configuration</h2><span class="badge blue">Capacity-based estimate</span></div><div class="form"><div class="timeline-fields">'+[['frontend','Frontend developers'],['backend','Backend developers'],['qa','QA engineers'],['hours','Working hours / day'],['days','Days / week'],['buffer','Buffer (%)']].map(([key,label])=>'<label class="field">'+label+'<input type="number" min="'+(['frontend','backend','qa','buffer'].includes(key)?0:1)+'" max="'+(key==='hours'?24:key==='days'?7:100)+'" value="'+t[key]+'" onchange="updateTimeline(\''+key+'\',this.value)"></label>').join('')+'<label class="field">Start date<input type="date" value="'+t.start+'" onchange="timelineState().start=this.value;render()"></label></div><p class="sub">Estimate assumes work can be shared across the team. Confirm dependencies and specialist capacity before approval.</p></div></section><section class="panel"><div class="panel-title"><h2>Estimated timeline</h2></div>'+table(['Workstream','Start date','End date','Estimated effort'],[['Requirements refinement','Design & architecture','Development','Testing & QA','Deployment'].map((title,i)=>[title,timelineDate(i,false),timelineDate(i,true),Math.round(calc.total*[.1,.15,.5,.2,.05][i])+' hours'])].flat())+'<div class="timeline-totals"><div><span>Estimated duration</span><b>'+calc.weeks+' weeks</b></div><div><span>Total effort + buffer</span><b>'+calc.total+' hours</b></div><div><span>Weekly capacity</span><b>'+calc.capacity+' hours</b></div></div></section><div class="page-actions">'+button('Approve plan & continue →','approveDeliveryPlan()',true)+'</div>'}
function timelineDate(i,end){const t=timelineState(),c=timelineCalc();if(!c.capacity||!t.start)return '—';const weights=[0,.1,.25,.75,.95,1],days=Math.max(5,c.weeks*7),d=new Date(t.start+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+Math.floor(days*weights[i+(end?1:0)])-(end?1:0));return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'})}
function updateTimeline(k,v){const n=Number(v),max=k==='hours'?24:k==='days'?7:100,min=['frontend','backend','qa','buffer'].includes(k)?0:1;if(!Number.isFinite(n)||n<min||n>max){toast('Enter a value between '+min+' and '+max+'.');render();return}timelineState()[k]=n;backlog().approved=false;render()}
function approveDeliveryPlan(){if(!current().approved)return toast('Approve the SRS baseline first.');if(!timelineCalc().capacity)return toast('Add at least one team member.');backlog().approved=true;track('Delivery plan approved','Planning');navigate('architecture')}
function architecturePage(){return appNav()+bpHeading('System architecture','Review the proposed components and the way they communicate.',button('Export design','exportArchitecture()'))+'<section class="panel architecture-panel"><div class="panel-title"><h2>Architecture diagram</h2><span class="badge blue">Illustrative system design</span></div><div class="architecture-canvas"><div class="arch-cloud">Cloud infrastructure</div><div class="connector-vertical"></div><div class="architecture-row"><div class="arch-node blue">'+icon('workspaces')+'<b>Frontend</b><small>Web application</small></div><div class="arch-node violet">'+icon('roles')+'<b>API gateway</b><small>Routing & authorization</small></div><div class="arch-node red">'+icon('projects')+'<b>Backend</b><small>Application services</small></div></div><div class="arch-row-connectors"><span>↓</span><span>↓</span><span>↓</span></div><div class="architecture-row"><div class="arch-node">'+icon('dashboard')+'<b>Database</b><small>Project & requirements data</small></div><div class="arch-node">'+icon('requirements')+'<b>Cache & queue</b><small>Background processing</small></div><div class="arch-node">'+icon('permissions')+'<b>Object storage</b><small>Documents & meeting artifacts</small></div></div></div></section><section class="panel"><div class="panel-title"><h2>Architecture decisions</h2></div><div class="form"><label class="field">Design notes<textarea id="architectureNotes" onchange="architectureState().doc=this.value">'+esc(architectureState().doc||'Enforce workspace and project authorization at the API. Store versioned baselines and an audit trail. Run transcription, translation, and notifications in background services. Confirm the technology stack and availability targets before implementation.')+'</textarea></label></div></section><div class="page-actions">'+button('Continue to test cases →',"navigate('tests')",true)+'</div>'}
function exportArchitecture(){downloadText('BlueprintReq-architecture.txt',architectureState().doc||'Illustrative architecture: Web client → API gateway → Backend services → Database, cache/queue, object storage. Technology choices require review.')}
let testStatuses={};
function testsPage(){return appNav()+bpHeading('Test cases','Define test coverage for each requirement and record manual outcomes.')+'<section class="panel">'+table(['ID','Test case','Requirement','Priority','Status'],backlog().rows.map((r,i)=>['TC-'+String(i+1).padStart(3,'0'),esc(r.ac),r.id,priorityTag(r.priority),'<select aria-label="Test outcome '+r.id+'" onchange="testStatuses[selected+\'-'+r.id+'\']=this.value"><option>Not run</option>'+['Passed','Failed','Blocked'].map(s=>'<option '+(testStatuses[selected+'-'+r.id]===s?'selected':'')+'>'+s+'</option>').join('')+'</select>']))+'</section><p class="sub">Test outcomes are entered manually. No automated tests are executed by this prototype.</p><div class="page-actions">'+button('View quality assurance →',"navigate('quality')",true)+'</div>'}
function qualityStats(){const rows=backlog().rows,total=rows.length,passed=rows.filter(r=>testStatuses[selected+'-'+r.id]==='Passed').length,failed=rows.filter(r=>testStatuses[selected+'-'+r.id]==='Failed').length;return{total,passed,failed,score:total?Math.round(passed/total*100):0,coverage:total?Math.round(rows.filter(r=>r.ac?.trim()).length/total*100):0}}
function qualityPage(){const q=qualityStats();return appNav()+bpHeading('Quality assurance','Review coverage, test outcomes, and open requirements before handoff.')+'<div class="quality-metrics"><section class="panel quality-score"><h2>Test pass rate</h2><div class="quality-ring" style="--score:'+q.score+'"><div><b>'+q.score+'</b><span>/ 100</span></div></div><small>'+q.passed+' of '+q.total+' tests passed</small></section><section class="panel coverage-metric"><span>Acceptance criteria coverage</span><strong>'+q.coverage+'%</strong><small>Requirements with written criteria</small></section><section class="panel coverage-metric"><span>Failed tests</span><strong>'+q.failed+'</strong><small>Based on manual test outcomes</small></section></div><section class="panel"><div class="panel-title"><h2>Key findings</h2></div><div class="finding-list"><a href="#tests"><span class="finding-icon amber">!</span><div><b>'+ (q.total-q.passed-q.failed)+' tests need execution or resolution</b><small>Record outcomes on the Test cases page.</small></div><span>→</span></a><a href="#requirements"><span class="finding-icon blue">i</span><div><b>'+backlog().rows.filter(r=>r.status!=='Approved').length+' requirements awaiting approval</b><small>Resolve drafts and review items before final delivery.</small></div><span>→</span></a><a href="#srs"><span class="finding-icon green">✓</span><div><b>'+ (current().approved?'SRS baseline approved':'SRS baseline needs approval')+'</b><small>Keep the implementation aligned with the approved scope.</small></div><span>→</span></a></div></section><div class="page-actions">'+button('View traceability →',"navigate('traceability')",true)+'</div>'}
function traceabilityPage(){return appNav()+bpHeading('Requirements traceability','Follow each requirement through stories, tests, and design.')+'<div class="trace-legend"><span><i class="trace-dot linked"></i> Linked</span><span><i class="trace-dot partial"></i> Proposed link</span><span><i class="trace-dot missing"></i> Not linked</span></div><section class="panel">'+table(['Requirement','User story','Test case','Design','Code'],backlog().rows.map((r,i)=>['<b>'+r.id+'</b>','<a href="#stories" class="trace-cell"><i class="trace-dot linked"></i>US-'+String(i+1).padStart(3,'0')+'</a>','<a href="#tests" class="trace-cell"><i class="trace-dot linked"></i>TC-'+String(i+1).padStart(3,'0')+'</a>','<a href="#architecture" class="trace-cell"><i class="trace-dot partial"></i>Application service</a>','<span class="trace-cell"><i class="trace-dot missing"></i>Not connected</span>']))+'</section><p class="sub">Story and test links reflect the current UI data. Design mappings are proposals; a code repository is not connected.</p>'}
const jpMeeting=[['Sahim','We need a clear approval owner for each deliverable.','各成果物の承認責任者を明確にする必要があります。'],['Maya','Clients should only see projects assigned to their organization.','顧客は自社に割り当てられたプロジェクトだけを閲覧できるようにします。'],['Alex','Every approval should include the reviewer and timestamp.','すべての承認に、レビュー担当者と日時を記録します。']];
let livePreview={playing:false,count:0,timer:null};
function liveMeetingPage(){return appNav()+bpHeading('Product requirements discussion','Zoom · Automatic transcription & translation workspace','<span class="meeting-state">'+(livePreview.playing?'Sample playback':'Not connected')+'</span>')+'<div class="meeting-setup"><label>Meeting link<input id="meetLink" value="'+esc(meetLinkValue)+'" oninput="meetLinkValue=this.value" placeholder="https://zoom.us/j/12345678901"></label>'+button('Open Zoom','openMeet()',true)+'<label>Translation<select onchange="meetingLanguage=this.value;render()"><option value="en-ja" '+(meetingLanguage==='en-ja'?'selected':'')+'>English → Japanese</option><option value="ja-en" '+(meetingLanguage==='ja-en'?'selected':'')+'>Japanese → English</option></select></label></div><div class="live-layout"><section class="meeting-video panel"><div class="participant-grid">'+[['SC','Sahim Chy','indigo'],['MC','Maya Chen','blue'],['AM','Alex Morgan','teal'],['You','You','slate']].map(([initial,name,color])=>'<div class="participant '+color+'"><span class="participant-avatar">'+initial+'</span><small>'+name+' · Preview</small></div>').join('')+'</div><div class="call-controls">'+button(livePreview.playing?'Pause preview':'▶ Play sample','playLivePreview()',true)+button('Reset','resetLivePreview()')+'</div><p class="meeting-disclaimer">Preview participants and sample text. No audio or video is captured. Live Zoom processing requires a connected meeting service.</p></section><section class="panel live-transcript"><div class="panel-title"><h2>Transcript & translation</h2></div><div class="transcript-languages"><span>Transcript · '+(meetingLanguage==='en-ja'?'English':'日本語')+'</span><span>Translation · '+(meetingLanguage==='en-ja'?'日本語':'English')+'</span></div><div class="live-lines">'+(livePreview.count?jpMeeting.slice(0,livePreview.count).map(([name,en,ja],i)=>'<div class="live-line"><small>00:'+String(i*8).padStart(2,'0')+' <b>'+name+'</b></small><p>'+esc(meetingLanguage==='en-ja'?en:ja)+'</p><p class="translated-line">'+esc(meetingLanguage==='en-ja'?ja:en)+'</p></div>').join(''):'<div class="empty">Play the sample to preview synchronized transcription and translation.</div>')+'</div></section></div>'}
function playLivePreview(){if(livePreview.playing){clearInterval(livePreview.timer);livePreview.playing=false;render();return}if(livePreview.count===3)livePreview.count=0;livePreview.playing=true;livePreview.count++;livePreview.timer=setInterval(()=>{livePreview.count++;if(livePreview.count>=3){livePreview.playing=false;clearInterval(livePreview.timer)}if(screen==='meetings')render()},1800);render()}
function resetLivePreview(){clearInterval(livePreview.timer);livePreview={playing:false,count:0,timer:null};render()}
function addLiveContext(){if(!livePreview.count)return toast('Play the sample first.');if(current().approved)return toast('Open a new SRS draft before adding context.');current().meeting=jpMeeting.slice(0,livePreview.count).map(([n,en,ja])=>n+': '+en+'\n'+ja).join('\n\n');docs()[1]+='\n\nMeeting context · Sample\n'+current().meeting;track('Meeting preview added to context','Requirements');navigate('srs')}
function homePage(){const ps=projects.filter(p=>p.space===workspace);return bpHeading('Good morning, '+esc(profile.name.split(' ')[0]),'Bring your ideas, conversations, and development plans together.',button('+ New project',"openCreate('project')",true))+'<div class="metrics">'+[['Active projects',ps.length,'projects'],['Approved baselines',ps.filter(p=>reqs[p.id]?.approved||p.status==='Approved').length,'roles'],['Team members',users.filter(u=>u.space===workspace).length,'teams'],['Session activity',usageEvents.filter(e=>e.space===workspace).length,'dashboard']].map(([t,n,i])=>'<div class="metric"><div class="metric-top">'+t+'<span class="metric-icon">'+icon(i)+'</span></div><strong>'+n+'</strong><small>Current workspace</small></div>').join('')+'</div><div class="home-actions"><a href="#request"><span class="input-icon">'+icon('requirements')+'</span><div><b>Start a new request</b><small>Capture your idea or upload a document</small></div><span>→</span></a><a href="#meetings"><span class="input-icon violet">'+icon('teams')+'</span><div><b>Record, transcribe & translate</b><small>Capture audio from your meeting</small></div><span>→</span></a></div><div class="dashboard-charts">'+panel('Workspace activity',workspace===0?lineChart():'<div class="empty">No activity history yet.</div>','<span class="badge gray">Sample data</span>')+panel('Requirements overview',bars([ps.filter(p=>reqs[p.id]?.approved||p.status==='Approved').length,ps.filter(p=>p.status==='In review').length,ps.filter(p=>p.status==='Draft').length],['Approved','In review','Draft']))+'</div>'+panel('Recent projects',projectTable(),'<a class="text-link" href="#projects">View all →</a>')}
function bpAuth(register=false){return '<div class="auth-shell"><div class="auth-wrap"><section class="auth-story"><a href="#dashboard" class="bp-brand">'+bpLogo()+'</a><div><span class="auth-kicker">AI PRODUCT DEVELOPMENT</span><h1>From conversations<br>to implementation.</h1><p>Transform ideas into clear requirements, architecture, and a ready-to-build plan with AI.</p><ul><li>AI-assisted requirements</li><li>Meeting audio transcription</li><li>Complete SRS to implementation</li><li>Built for modern teams</li></ul></div><small>Your team’s next idea starts here.</small></section><section class="auth-form"><h1>'+(register?'Create your account':'Welcome back')+'</h1><p class="sub">'+(register?'Start building better products with AI.':'Sign in to your account')+'</p><button class="google-login" type="button" onclick="googleLogin()"><span class="google-mark">G</span> '+(register?'Sign up with Google':'Continue with Google')+'</button><div class="auth-or"><span>or continue with email</span></div><form onsubmit="bpAuthSubmit(event,'+register+')">'+(register?field('Full name','name'):'')+field('Email address','email','','email')+'<label class="field">Password<input type="password" name="password" minlength="8" required autocomplete="'+(register?'new-password':'current-password')+'"></label>'+(register?'<label class="field">Confirm password<input type="password" name="confirm" minlength="8" required autocomplete="new-password"></label>':'')+'<button class="primary">'+(register?'Create demo account':'Sign in to demo')+'</button></form><p class="auth-switch">'+(register?'Already have an account? <a href="#login">Sign in</a>':'Don’t have an account? <a href="#register">Create account</a>')+'</p><a class="explore-link" href="#dashboard">Explore the demo workspace →</a><div class="auth-note">Interactive UI preview. Google OAuth and email authentication require a connected backend. This button opens a demo session; passwords are not stored or sent.</div></section></div></div>'}
function googleLogin(){profile.name='Google User';profile.email='google.user@example.com';navigate('dashboard');toast('Google sign-in demo opened. Connect OAuth to enable real accounts.')}
function bpAuthSubmit(e,register){e.preventDefault();const f=new FormData(e.target);if(register&&f.get('password')!==f.get('confirm'))return toast('Passwords do not match.');authSubmit(e,register)}
const blueprintPageRoutes={dashboard:homePage,request:requestPage,meetings:liveMeetingPage,srs:srsPage,baseline:baselinePage,requirements:requirementsPage,stories:storiesPage,timeline:timelinePage,architecture:architecturePage,tests:testsPage,quality:qualityPage,traceability:traceabilityPage,projects:listProjects,workspaces:workspaceScreen,teams:teamScreen,users:userScreen,roles:roleScreen,permissions:permissionsScreen,usage:usageScreen,profile:profileScreen,create:creationScreen};
render=function(){if(screen==='planning')screen='timeline';if(screen==='login'||screen==='register'){$('#root').innerHTML=bpAuth(screen==='register');return}const projectScreens=['request','meetings','srs','baseline','requirements','stories','timeline','architecture','tests','quality','traceability'];let html;if(projectScreens.includes(screen)&&!projectReady())html=emptyProject();else html=(blueprintPageRoutes[screen]||homePage)();$('#root').innerHTML=bpShell(html)};
window.addEventListener('hashchange',()=>document.body.classList.remove('bp-nav-open'));
render();
/* Latest workflow refinements */
const _createItemForRequest=createItem;
createItem=function(e,type){const beforeIds=projects.map(p=>p.id);_createItemForRequest(e,type);if(type==='project'){const created=projects.filter(p=>p.space===workspace&&!beforeIds.includes(p.id)).sort((a,b)=>b.id-a.id)[0];if(created){selected=created.id;requestMode='text';navigate('request');toast('Project created. Add its requirements to continue.')}}};
function proposeSectionPrompt(){const prompt=String($('#sectionAiPrompt')?.value||'').trim();if(!prompt)return toast('Write a prompt for the section first.');sectionSave();if(current().approved)return toast('Create a new draft to change an approved baseline.');aiProposals[selected+'-'+sectionIndex]='Prompt request: '+prompt+'\n\nSuggested refinement: clarify the user, the expected behavior, measurable outcomes, and any important constraints for this section. Confirm the proposed wording with stakeholders before accepting.';track('Section prompt previewed','Requirements');render()}
const _srsPageWithPrompt=srsPage;
srsPage=function(){return _srsPageWithPrompt().replace('<div class="ai-limit">Example suggestions only. An AI service is not connected.</div>','<label class="field ai-prompt-field">Prompt AI for this section<input id="sectionAiPrompt" placeholder="e.g. Make the acceptance criteria measurable"><button type="button" onclick="proposeSectionPrompt()">Generate suggestion</button></label><div class="ai-limit">Example suggestions only. An AI service is not connected.</div>')};
const _baselinePageNoRemarks=baselinePage;
baselinePage=function(){return _baselinePageNoRemarks().replace(/<label class="field">Review comments \(optional\)<textarea class="short-text" id="reviewComment" placeholder="Add your comments…"><\/textarea><\/label>/,'')};
function aiAddRequirementPrompt(){const prompt=String($('#requirementAiPrompt')?.value||'').trim();if(!prompt)return toast('Write a prompt for the new requirement first.');if(backlog().approved)return toast('Create a new planning draft before adding requirements.');const p=backlog(),n=p.rows.length+1;p.rows.push({id:'REQ-'+String(n).padStart(3,'0'),module:'AI suggested',story:prompt,ac:'AI proposal: define a measurable outcome and confirm the acceptance condition with stakeholders.',priority:'Medium',hours:8,status:'Draft'});track('Prompted AI requirement added','Planning');render();toast('AI requirement draft added. Review it before approval.')}
const _requirementsPageWithPrompt=requirementsPage;
requirementsPage=function(){return _requirementsPageWithPrompt().replace("button('✦ Add with AI','aiAddRequirement()',false)","<label class=\"inline-ai-prompt\"><span>✦</span><input id=\"requirementAiPrompt\" placeholder=\"Prompt AI to add a requirement…\"><button type=\"button\" onclick=\"aiAddRequirementPrompt()\">Generate</button></label>")};
function aiAddStoryPrompt(){const prompt=String($('#storyAiPrompt')?.value||'').trim();if(!prompt)return toast('Write a prompt for the user story first.');const p=backlog(),n=p.rows.length+1;p.rows.push({id:'REQ-'+String(n).padStart(3,'0'),module:'AI suggested',story:prompt,ac:'AI proposal: define the observable pass/fail behavior for this story.',priority:'Medium',hours:8,status:'Draft'});track('Prompted AI story added','Planning');render();toast('AI user story draft added. Review the acceptance criteria.')}
const _storiesPageWithPrompt=storiesPage;
storiesPage=function(){return _storiesPageWithPrompt().replace("button('✦ Add with AI','aiAddStory()',false)","<label class=\"inline-ai-prompt\"><span>✦</span><input id=\"storyAiPrompt\" placeholder=\"Prompt AI to add a user story…\"><button type=\"button\" onclick=\"aiAddStoryPrompt()\">Generate</button></label>")};
function aiAddTestPrompt(){const prompt=String($('#testAiPrompt')?.value||'').trim();if(!prompt)return toast('Write a prompt for the test case first.');const p=backlog(),n=p.rows.length+1;p.rows.push({id:'REQ-'+String(n).padStart(3,'0'),module:'AI suggested',story:prompt,ac:'AI proposal: define the expected test result and failure condition.',priority:'Medium',hours:4,status:'Draft'});track('Prompted AI test case added','Quality');render();toast('AI test case draft added. Review the linked requirement.')}
const _testsPageWithPrompt=testsPage;
testsPage=function(){return _testsPageWithPrompt().replace("button('✦ Add with AI','aiAddTest()',false)","<label class=\"inline-ai-prompt\"><span>✦</span><input id=\"testAiPrompt\" placeholder=\"Prompt AI to add a test case…\"><button type=\"button\" onclick=\"aiAddTestPrompt()\">Generate</button></label>")};
render();
function usageBar(label,used,limit,color){const pct=Math.min(100,Math.round(used/limit*100));return '<div class="usage-limit"><div><b>'+label+'</b><span>'+used.toLocaleString()+' / '+limit.toLocaleString()+'</span></div><div class="usage-track"><i class="'+color+'" style="width:'+pct+'%"></i></div><small>'+pct+'% used · resets '+(label==='Daily'?'tomorrow':'next Monday')+'</small></div>'}
function enhancedUsageScreen(){const events=usageEvents.filter(e=>e.space===workspace),daily=Math.min(100,events.length*4),weekly=Math.min(500,events.length*12);return bpHeading('Usage','Monitor your workspace activity and plan limits.',button('Export activity CSV','exportUsage()'))+'<div class="notice">Usage shown here is sample session activity. Connect billing and AI services to calculate real token and meeting consumption.</div><div class="usage-limits-grid"><section class="panel"><div class="panel-title"><h2>Daily limit</h2><span class="badge blue">Today</span></div><div class="usage-panel-body">'+usageBar('Daily',daily,100,'blue-fill')+'</div></section><section class="panel"><div class="panel-title"><h2>Weekly limit</h2><span class="badge violet">This week</span></div><div class="usage-panel-body">'+usageBar('Weekly',weekly,500,'violet-fill')+'</div></section></div><div class="metrics">'+[['Tracked actions',events.length],['AI tokens','—'],['Meeting minutes','—'],['Translation characters','—']].map(([t,n])=>'<div class="metric"><div class="metric-top">'+t+'</div><strong>'+n+'</strong><small>Service not connected</small></div>').join('')+'</div>'+panel('Activity by phase',bars(['Requirements','Planning','Architecture'].map(p=>events.filter(e=>e.phase===p).length),['Requirements','Planning','Architecture']))+panel('Activity log',table(['Time','Project','Phase','Action'],events.slice().reverse().map(e=>[e.time,esc(projects.find(p=>p.id===e.project)?.name||'Project'),e.phase,esc(e.action)])),'','Session activity')}
usageScreen=enhancedUsageScreen;
function aiAddRequirement(){if(!current().approved){const p=backlog();const n=p.rows.length+1;p.rows.push({id:'REQ-'+String(n).padStart(3,'0'),module:'AI suggested',story:'As a user, I want a clear next action after each workflow step.',ac:'Given a completed step, the next available action is visible and the user can continue without losing work.',priority:'Medium',hours:12,status:'Draft'});track('AI suggested requirement added','Planning');render();toast('Example AI requirement added. Review it before approval.')}else toast('Create a new planning draft before adding requirements.')}
function aiAddStory(){const p=backlog();const n=p.rows.length+1;p.rows.push({id:'REQ-'+String(n).padStart(3,'0'),module:'AI suggested',story:'receive a clear status update for my work',ac:'The status is visible and updated after the workflow action completes.',priority:'Medium',hours:12,status:'Draft'});track('AI suggested user story added','Planning');render();toast('Example AI user story added. Review the acceptance criteria.')}
function aiAddTest(){const p=backlog();const n=p.rows.length+1;p.rows.push({id:'REQ-'+String(n).padStart(3,'0'),module:'AI suggested',story:'workflow status validation',ac:'Given a completed step, the next step is enabled and unavailable steps remain hidden.',priority:'Medium',hours:8,status:'Draft'});track('AI suggested test case added','Quality');render();toast('Example AI test case added. Review the linked requirement.')}
const _requirementsPage=requirementsPage;
requirementsPage=function(){return _requirementsPage().replace("button('+ Add requirement','editRequirement()',true)","button('✦ Add with AI','aiAddRequirement()',false)+button('+ Add requirement','editRequirement()',true)")};
const _storiesPage=storiesPage;
storiesPage=function(){return _storiesPage().replace("button('+ Add story','editRequirement()',true)","button('✦ Add with AI','aiAddStory()',false)+button('+ Add story','editRequirement()',true)")};
const _testsPage=testsPage;
testsPage=function(){return _testsPage().replace("bpHeading('Test cases','Define test coverage for each requirement and record manual outcomes.')", "bpHeading('Test cases','Define test coverage for each requirement and record manual outcomes.',button('✦ Add with AI','aiAddTest()',false))")};
render();

// Bind routes after refinements; route entries must use the final renderers.
function promptPanel(id,label,action){return '<section class="panel" style="padding:20px;margin-bottom:24px"><label class="field">'+label+'<textarea id="'+id+'" placeholder="Describe what you want to add"></textarea></label><button class="primary" onclick="'+action+'()">Generate draft</button><p class="sub">Demo prompt preview. An AI service is not connected.</p></section>'}
blueprintPageRoutes.srs=srsPage;
blueprintPageRoutes.baseline=baselinePage;
blueprintPageRoutes.requirements=()=>promptPanel('requirementAiPrompt','Add a requirement with AI','aiAddRequirementPrompt')+_requirementsPageWithPrompt();
blueprintPageRoutes.stories=()=>promptPanel('storyAiPrompt','Add a user story with AI','aiAddStoryPrompt')+_storiesPageWithPrompt();
blueprintPageRoutes.tests=()=>promptPanel('testAiPrompt','Add a test case with AI','aiAddTestPrompt')+_testsPageWithPrompt();
blueprintPageRoutes.usage=enhancedUsageScreen;
