// Project accordion and form-scoped assistance.
toggleProjectGroup=function(id){const wasOpen=selected===id&&!collapsedProjects.has(id);selected=id;collapsedProjects=new Set(wasOpen?[id]:[]);render()};
function assistedField(label,name,value,action,multiline=false){return '<div class="field"><label for="assist-'+name+'">'+label+'</label><div class="assisted-input">'+(multiline?'<textarea id="assist-'+name+'" name="'+name+'" required>'+esc(value)+'</textarea>':'<input id="assist-'+name+'" name="'+name+'" value="'+esc(value)+'" required>')+'<button type="button" onclick="'+action+'()">✦ Generate with AI</button></div></div>'}

editRequirement=function(id){const r=backlog().rows.find(r=>r.id===id)||{story:'',module:'General',priority:'Medium'};creationPage={title:id?'Edit requirement':'Add requirement',back:'requirements',body:assistedField('Requirement name','story',r.story,'draftRequirementFields')+field('Module','module',r.module)+'<label class="field">Priority<select name="priority">'+['High','Medium','Low'].map(p=>'<option '+(p===r.priority?'selected':'')+'>'+p+'</option>').join('')+'</select></label>',submit:"saveRequirement(event,'"+(id||'')+"')"};navigate('create')};
function draftRequirementFields(){const prompt=document.querySelector('[name="story"]').value.trim();if(!prompt)return toast('Describe the requirement first.');document.querySelector('[name="story"]').value=prompt.replace(/^(please |i want |we need )/i,'').replace(/^./,c=>c.toUpperCase());document.querySelector('[name="module"]').value=/login|sign|password|account/i.test(prompt)?'Authentication':/payment|checkout|invoice/i.test(prompt)?'Billing':'General';toast('Demo draft filled. Review the name and module before saving.')}
saveRequirement=function(e,id){e.preventDefault();const f=new FormData(e.target),name=String(f.get('story')||'').trim();if(!name)return toast('Enter a requirement name.');const p=backlog(),r=p.rows.find(r=>r.id===id);const values={story:name,module:String(f.get('module')||'General'),priority:f.get('priority')||'Medium'};if(r)Object.assign(r,values);else p.rows.push({...values,id:'REQ-'+String(p.rows.length+1).padStart(3,'0'),ac:'',hours:0,status:'Draft'});p.approved=false;p.reviewed=false;delete architectures[selected];track('Requirement updated','Planning');navigate('requirements')};
function editStory(id){const rows=backlog().rows,r=rows.find(r=>r.id===id);creationPage={title:r?'Edit user story':'Add user story',back:'stories',body:'<label class="field">Requirement<select name="requirement" required>'+rows.map(x=>'<option value="'+x.id+'" '+(x.id===id?'selected':'')+'>'+esc(x.id+' · '+x.story)+'</option>').join('')+'</select></label>'+assistedField('User story','userStory',r?.userStory||'','draftStoryFields',true)+'<label class="field">Acceptance criteria<textarea name="acceptance" required>'+esc(r?.ac||'')+'</textarea></label>',submit:'saveStory(event)'};navigate('create')}
function draftStoryFields(){const id=document.querySelector('[name="requirement"]').value,r=backlog().rows.find(x=>x.id===id);if(!r)return toast('Choose a requirement first.');const prompt=document.querySelector('[name="userStory"]').value.trim();if(!prompt)return toast('Enter your story idea in the user story field first.');document.querySelector('[name="userStory"]').value='As a user, I want '+r.story+' so that I can achieve the intended outcome.'+(prompt?' '+prompt:'');document.querySelector('[name="acceptance"]').value='Given the user has access, when they perform '+r.story+', then the expected result is displayed.\nInvalid input displays a clear error and preserves entered data.';toast('Demo story and criteria filled for '+id+'. Review before saving.')}
function saveStory(e){e.preventDefault();const f=new FormData(e.target),r=backlog().rows.find(x=>x.id===f.get('requirement'));if(!r)return toast('Choose a requirement.');r.userStory=String(f.get('userStory')||'').trim();r.ac=String(f.get('acceptance')||'').trim();if(!r.userStory||!r.ac)return toast('Complete the story and acceptance criteria.');track('User story updated','Planning');navigate('stories')}
blueprintPageRoutes.requirements=_requirementsPageWithPrompt;
blueprintPageRoutes.tests=_testsPageWithPrompt;
blueprintPageRoutes.stories=function(){return appNav()+bpHeading('User stories & acceptance criteria','Write stories for the requirements you choose.',button('+ Add story','editStory()',true))+'<div class="story-list">'+backlog().rows.map(r=>'<section class="panel story-card"><b>'+esc(r.id+' · '+r.story)+'</b><h2>'+esc(r.userStory||'No user story added yet')+'</h2><div class="acceptance"><b>Acceptance criteria</b><p>'+esc(r.ac||'Not defined yet')+'</p></div>'+button('Edit story details',"editStory('"+r.id+"')")+'</section>').join('')+'</div><div class="page-actions">'+button('Generate timeline →',"navigate('timeline')",true)+'</div>'};
render();
const priorCreateMembers=openCreate;
function membershipStatus(u){return u.status==='Pending invitation'?'Unregistered':u.verified===true?'Verified':'Registered · verification unknown'}
function memberRows(list,members=[],memberRoles={},showRoles=true){return list.map(u=>'<div class="membership-row"><label><input type="checkbox" name="member" value="'+u.id+'" '+(members.includes(u.id)?'checked':'')+'><span>'+esc(u.name)+'<small>'+esc(u.email)+' · '+membershipStatus(u)+'</small></span></label>'+(showRoles?'<select aria-label="Role for '+esc(u.name)+'" name="role_'+u.id+'">'+roles.map(r=>'<option '+(r===(memberRoles[u.id]||u.role||'Editor')?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select>':'')+'</div>').join('')}
function manageEntity(type,id){const collection=type==='workspace'?spaces:type==='team'?teams:projects,obj=collection.find(x=>x.id===id),space=obj?.space??(type==='workspace'&&obj?obj.id:workspace);let list=users.filter(u=>u.space===space);if(type==='workspace'&&!obj)list=[...new Map(users.map(u=>[u.email,u])).values()];const assigned=type==='workspace'&&obj?list.map(u=>u.id):obj?.members||[];creationPage={title:(obj?'Manage ':'Create ')+type,back:type==='workspace'?'workspaces':type==='team'?'teams':'projects',body:field('Name','name',obj?.name||'')+field('Description','desc',obj?.desc||'')+(type==='project'?'<label class="field">Team<select name="team" onchange="selectTeamMembers(this.value)"><option value="0">No team</option>'+teams.filter(t=>t.space===space).map(t=>'<option value="'+t.id+'" '+(obj?.team===t.id?'selected':'')+'>'+esc(t.name)+'</option>').join('')+'</select><small>Choosing a team selects its workspace members.</small></label>':'')+'<fieldset class="people-picker"><legend>Workspace members</legend>'+memberRows(list,assigned,obj?.memberRoles||{},type==='workspace')+'</fieldset>'+(type==='workspace'?'<div class="field"><label>Add unregistered member (optional)</label><input name="pendingEmail" type="email" placeholder="person@example.com"><label>Role for this member</label><select name="pendingRole">'+roles.filter(r=>r!=='Owner').map(r=>'<option>'+esc(r)+'</option>').join('')+'</select><small>No invitation email is sent in this preview.</small></div>':''),submit:"saveEntityMembers(event,'"+type+"',"+(obj?id:'null')+")"};navigate('create')}
openCreate=function(type){if(['workspace','team','project'].includes(type))return manageEntity(type,null);priorCreateMembers(type)};
manageTeam=function(id){manageEntity('team',id)};
function selectTeamMembers(id){const t=teams.find(t=>t.id===Number(id)&&t.space===workspace);if(!t)return;for(const uid of t.members){const box=document.querySelector('input[name="member"][value="'+uid+'"]');if(box)box.checked=true;const role=document.querySelector('[name="role_'+uid+'"]');if(role&&t.memberRoles?.[uid])role.value=t.memberRoles[uid]}}
function saveEntityMembers(e,type,id){e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')||'').trim();if(!name)return toast('Enter a name.');const collection=type==='workspace'?spaces:type==='team'?teams:projects;let obj=collection.find(x=>x.id===id),fresh=!obj,target=type==='workspace'?(obj?.id??spaces.length):workspace;const allowed=users.filter(u=>type==='workspace'&&!obj||u.space===target),chosen=f.getAll('member').map(Number).filter(uid=>allowed.some(u=>u.id===uid));let memberRoles={};const members=chosen.map(uid=>{const user=users.find(u=>u.id===uid),role=String(type==='workspace'?(f.get('role_'+uid)||user.role||'Editor'):(user.role||'Editor'));const mapped=type==='workspace'?ensureMember(user,target,role):uid;memberRoles[mapped]=role;if(type==='workspace')users.find(u=>u.id===mapped).role=role;return mapped});const email=String(f.get('pendingEmail')||'').trim();if(type==='workspace'&&email){const uid=ensureMember({name:email.split('@')[0],email,status:'Pending invitation'},target,String(f.get('pendingRole')||'Editor'));members.push(uid);memberRoles[uid]=String(f.get('pendingRole')||'Editor')}
if(!obj){obj={id:type==='workspace'?target:Date.now(),space:target,status:'Draft',progress:0};collection.push(obj)}Object.assign(obj,{name,desc:String(f.get('desc')||''),members:[...new Set(members)],memberRoles});if(type!=='workspace')delete obj.memberRoles;if(type==='project'){const team=teams.find(t=>t.id===Number(f.get('team'))&&t.space===target);obj.team=team?.id||0}if(type==='workspace'){workspace=target;selected=projects.find(p=>p.space===target)?.id||0}if(type==='project'&&fresh){selected=obj.id;requestMode='text';navigate('request')}else navigate(type==='workspace'?'workspaces':type==='team'?'teams':'projects');toast('Membership and individual roles saved for this session.')}
const originalProjectTableMembers=projectTable;
projectTable=function(){return originalProjectTableMembers()+ '<div class="panel" style="padding:20px"><h2>Manage project access</h2>'+projects.filter(p=>p.space===workspace).map(p=>'<div class="membership-row"><span>'+esc(p.name)+'</span>'+button('Manage members',"manageEntity('project',"+p.id+")")+'</div>').join('')+'</div>'};
const originalWorkspaceMembers=blueprintPageRoutes.workspaces;
blueprintPageRoutes.workspaces=function(){return originalWorkspaceMembers()+'<div class="panel" style="padding:20px"><h2>Manage workspace membership</h2>'+spaces.map(w=>'<div class="membership-row"><span>'+esc(w.name)+'</span>'+button('Members & roles',"manageEntity('workspace',"+w.id+")")+'</div>').join('')+'</div>'};
render();

blueprintPageRoutes.users=function(){return bpHeading('User management','View invited and registered people and manage workspace roles.',button('+ Add user',"openCreate('user')",true))+panel('Workspace members',table(['Member','Registration','Workspace role','Account status','Actions'],users.filter(u=>u.space===workspace).map(u=>{const invited=u.status==='Pending invitation';return [esc(u.name)+'<small style="display:block">'+esc(u.email)+'</small>',badge(invited?'Invited · not registered':'Registered'),'<select aria-label="Workspace role for '+esc(u.name)+'" onchange="changeRole('+u.id+',this.value)" '+(u.id===1?'disabled':'')+'>'+roles.map(r=>'<option '+(r===u.role?'selected':'')+'>'+esc(r)+'</option>').join('')+'</select>',badge(u.status),invited?'<span class="sub">Awaiting registration</span>':u.id===1?'Workspace owner':button(u.status==='Active'?'Suspend':'Activate','toggleUser('+u.id+')')]})))+'<p class="sub">Invitation and registration statuses are prototype data; no invitation email is sent.</p>'};render();
const renderWithDeeperTheme=render;
let lastAnimatedPage='';
render=function(){const pageKey=screen+':'+selected;renderWithDeeperTheme();if(pageKey!==lastAnimatedPage){document.querySelector('.bp-main')?.classList.add('page-enter');lastAnimatedPage=pageKey}};
render();

let interfaceLanguage='en';
const shellWithLanguage=bpShell;
bpShell=function(content){return shellWithLanguage(content).replace('<div class="header-tools">','<div class="header-tools"><select class="interface-language" aria-label="Interface language" onchange="setInterfaceLanguage(this.value)"><option value="en" '+(interfaceLanguage==='en'?'selected':'')+'>English</option><option value="ja" '+(interfaceLanguage==='ja'?'selected':'')+'>日本語</option></select>')};
function setInterfaceLanguage(value){interfaceLanguage=value==='ja'?'ja':'en';render()}
const localizedLabels={'Home':'ホーム','New project':'新規プロジェクト','WORKSPACE':'ワークスペース','PROJECTS':'プロジェクト','ORGANIZATION':'組織','Dashboard':'ダッシュボード','Projects':'プロジェクト','Team':'チーム','Teams':'チーム','Workspaces':'ワークスペース','User management':'ユーザー管理','Roles':'ロール','Permissions':'権限','Usage':'使用状況','SRS document':'SRS文書','Baseline approval':'ベースライン承認','Requirements':'要件','User stories':'ユーザーストーリー','Timeline':'スケジュール','Architecture':'アーキテクチャ','Test cases':'テストケース','Quality assurance':'品質保証','Traceability':'トレーサビリティ','Workspace owner':'ワークスペース所有者','Interactive preview':'インタラクティブプレビュー','Create':'作成','Cancel':'キャンセル','Save':'保存','Transcript & translation':'文字起こしと翻訳'};
const renderLanguageBase=render;
render=function(){renderLanguageBase();if(document.documentElement)document.documentElement.lang=interfaceLanguage;if(interfaceLanguage==='ja'&&document.createTreeWalker){const root=document.querySelector('#root'),walker=document.createTreeWalker(root,4);let n;while(n=walker.nextNode()){if(['TEXTAREA','SCRIPT','STYLE','OPTION'].includes(n.parentElement?.tagName))continue;const key=n.nodeValue.trim();if(localizedLabels[key])n.nodeValue=n.nodeValue.replace(key,localizedLabels[key]);}}};render();
const exportLanguageDrafts={};
function exportSections(){sectionSave();const box=document.getElementById('modal');box.innerHTML='<form onsubmit="performSrsExport(event)"><div class="export-heading"><span class="export-icon">↧</span><div><h2>Export document</h2><p class="sub">Choose what to share and how to save it.</p></div></div><div class="form"><label class="field">Content<select id="exportScope" onchange="updateExportChoices()"><option value="full">Complete SRS</option><option value="functional">Functional requirements only</option></select></label><label class="field">File format<select id="exportFormat"><option value="docx">▤ Word document (.docx)</option><option value="pdf">▧ PDF document (.pdf)</option><option value="xlsx">▦ Excel workbook (.xlsx)</option></select></label><label class="field">Language<select id="exportLanguage" onchange="updateExportChoices()"><option value="en">English</option><option value="ja">日本語</option></select></label><p id="exportNotice" class="sub"></p><div id="exportProgress" hidden role="status" aria-live="polite"><div class="export-progress-track"><span id="exportProgressFill"></span></div><p id="exportProgressLabel">Preparing your document…</p></div></div><div class="form-footer"><button type="button" onclick="document.getElementById(\'modal\').close()">Close</button><button class="primary" id="exportGo">↧ Export document</button></div></form>';box.showModal();updateExportChoices()}
function getExportSections(){const scope=document.getElementById('exportScope').value,lang=document.getElementById('exportLanguage').value,ja=['はじめに','全体概要','機能要件','非機能要件','業務ルール','前提条件と制約','用語集'];return (scope==='full'?sectionTitles.map((_,i)=>i):[2]).map(i=>{const source=docs()[i],matches=lang==='ja'?/[\u3040-\u30ff\u3400-\u9fff]/.test(source):!/[\u3040-\u30ff\u3400-\u9fff]/.test(source);return {title:lang==='ja'?ja[i]:sectionTitles[i],text:exportLanguageDrafts[selected+'-'+lang+'-'+i]??(matches?source:'')}})}
function updateExportChoices(){const scope=document.getElementById('exportScope').value,format=document.getElementById('exportFormat');format.querySelector('[value="xlsx"]').disabled=scope!=='functional';if(scope==='full'&&format.value==='xlsx')format.value='docx';const missing=getExportSections().some(s=>!s.text.trim());document.getElementById('exportGo').disabled=missing;document.getElementById('exportNotice').textContent=missing?'A translated version is not available for this language. Automatic translation is not connected.':'PDF opens the print dialog. Choose Save as PDF to finish.'}
function exportProgress(percent,label){document.getElementById('exportProgress').hidden=false;document.getElementById('exportProgressFill').style.width=percent+'%';document.getElementById('exportProgressLabel').textContent=label}
function downloadExportBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function performSrsExport(e){e.preventDefault();const format=document.getElementById('exportFormat').value,scope=document.getElementById('exportScope').value,lang=document.getElementById('exportLanguage').value,ja=['はじめに','全体概要','機能要件','非機能要件','業務ルール','前提条件と制約','用語集'],sections=getExportSections();if(sections.some(s=>!s.text.trim()))return toast('Complete the export text first.');const title=appProject().name+' — '+(scope==='full'?'SRS':lang==='ja'?'機能要件':'Functional requirements'),filename='BlueprintReq-'+scope+'-'+lang;
document.getElementById('exportGo').disabled=true;exportProgress(15,'Preparing document…');try{await new Promise(resolve=>setTimeout(resolve,50));exportProgress(40,'Creating your file…');if(format==='docx'){const d=window.docx,children=[new d.Paragraph({text:title,heading:d.HeadingLevel.TITLE})];sections.forEach(s=>{children.push(new d.Paragraph({text:s.title,heading:d.HeadingLevel.HEADING_1}));s.text.split('\n').forEach(text=>children.push(new d.Paragraph({children:[new d.TextRun({text,font:'Yu Gothic'})]})))});const blob=await d.Packer.toBlob(new d.Document({sections:[{children}]}));downloadExportBlob(blob,filename+'.docx')}
else if(format==='xlsx'){const rows=[[lang==='ja'?'機能要件':'Functional requirements'],...sections[0].text.split(/\n\s*\n/).filter(x=>x.trim()).map(x=>[x])],book=XLSX.utils.book_new(),sheet=XLSX.utils.aoa_to_sheet(rows);sheet['!cols']=[{wch:110}];XLSX.utils.book_append_sheet(book,sheet,'Requirements');XLSX.writeFile(book,filename+'.xlsx')}
else{const win=window.open('','_blank');if(!win)return toast('Allow the print window to open and try again.');win.document.write('<!doctype html><html lang="'+lang+'"><head><meta charset="utf-8"><title>'+esc(filename)+'</title><style>body{font:12pt "Yu Gothic","Noto Sans JP",sans-serif;color:#172b4b;padding:24px}h1{font-size:22pt}h2{font-size:16pt;break-after:avoid}p{white-space:pre-wrap;line-height:1.6}@page{size:A4;margin:18mm}</style></head><body><h1>'+esc(title)+'</h1>'+sections.map(s=>'<h2>'+esc(s.title)+'</h2><p>'+esc(s.text)+'</p>').join('')+'</body></html>');win.document.close();win.focus();setTimeout(()=>win.print(),350)}exportProgress(100,format==='pdf'?'Print preview opened — choose Save as PDF.':'Your file is ready. Download started.');toast(format==='pdf'?'Print preview opened. Choose Save as PDF.':'Download started.')}catch(error){toast('Export failed. Please try again.');console.error(error);exportProgress(0,'Export failed. Please try again.')}finally{document.getElementById('exportGo').disabled=false}}

// Timeline configuration and generated results are separate screens.
const generatedTimelines={};
pageNames['timeline-result']='Estimated project timeline';
const combinedTimelinePage=timelinePage;
blueprintPageRoutes.timeline=function(){
 const html=combinedTimelinePage(),cut=html.indexOf('<section class="panel"><div class="panel-title"><h2>Estimated timeline');
 return html.slice(0,cut).replace(/onchange="[^"]*"/g,'').replace('<div class="timeline-fields">','<div id="timelineInputs" class="timeline-fields">')+'<p class="sub">Prototype estimate based on requirement effort and team capacity. AI analysis is not connected.</p><div class="page-actions">'+button('Generate estimated timeline →','generateTimelineResult()',true)+'</div>';
};
function generateTimelineResult(){
 const fields=[...document.querySelectorAll('#timelineInputs input')],keys=['frontend','backend','qa','hours','days','buffer','start'];
 if(fields.length!==7)return;
 for(const el of fields){if(!el.value||!el.checkValidity()){el.reportValidity();el.focus();return}}
 const t=Object.fromEntries(keys.map((k,i)=>[k,k==='start'?fields[i].value:Number(fields[i].value)]));
 if(t.frontend+t.backend+t.qa===0)return toast('Add at least one team member.');
 if(!backlog().rows.length)return toast('Add requirements before estimating the timeline.');
 if(!backlog().rows.some(r=>Number(r.hours)>0))return toast('Requirement effort estimates are needed before a timeline can be calculated.');
 timelineSettings[selected]=t;backlog().approved=false;
 const project=selected;
 const overlay=document.createElement('div');overlay.className='workflow-loading';overlay.setAttribute('role','status');overlay.innerHTML='<span class="workflow-spinner"></span><div><b>Preparing your estimated timeline…</b><p>Calculating effort, team capacity and buffer</p></div>';document.body.appendChild(overlay);
 setTimeout(()=>{try{const html=combinedTimelinePage(),cut=html.indexOf('<section class="panel"><div class="panel-title"><h2>Estimated timeline');generatedTimelines[project]=html.slice(cut);navigate('timeline-result')}finally{overlay.remove()}},800);
}
blueprintPageRoutes['timeline-result']=function(){
 if(!selected||!generatedTimelines[selected])return bpHeading('No timeline generated yet','Configure your team to prepare an estimate.',button('Configure timeline',"navigate('timeline')",true));
 return appNav()+bpHeading('Estimated project timeline','Capacity-based estimate · Review before approving.',button('← Edit configuration',"navigate('timeline')"))+'<p class="sub">This prototype uses requirement effort and the submitted team configuration, with work shared across the team. AI analysis, specialist constraints and dependency analysis are not connected.</p>'+generatedTimelines[selected];
};
render();
